window.kbPageData["views/entry/k-67e25d7dcabb7f0b"] = {"key":"entry/k-67e25d7dcabb7f0b","state":{"route":"entry/k-67e25d7dcabb7f0b"},"node":{"id":"k-67e25d7dcabb7f0b","mode":"k","title":"固定增长率下的逐年复合增长","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2025 B类 行测#119"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"若指标从起点值 P 出发，每年均按同一增长率 r 相对上年增长，则 n 年后的数值为 P×(1+r)ⁿ。比较各指标何时达标，应分别求使预测值达到或超过各自目标的最小整年数。","review":{"definition":"若指标从起点值 P 出发，每年均按同一增长率 r 相对上年增长，则 n 年后的数值为 P×(1+r)ⁿ。比较各指标何时达标，应分别求使预测值达到或超过各自目标的最小整年数。","explanation":"本题以2023年数值为起点，用各指标的2023年同比增长率逐年推算，目标是各自2019年数值的2倍。中医药从业人员数从2022年的45957人增至2023年的50623人，增长率约为10.15%，目标为80100人。用未四舍五入的增长率推算，4年后约74530人，5年后约82097人，因此第5年达标。同法算得中医类医院数、实有床位数和中医医院患者门诊次均费用分别在第43年、第30年和第10年达标，故选B。","references":[],"evidence":"按2023年的增长率估算，江苏省中医服务的下列指标率先达到2019年水平2倍的是","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#119":{"paper":"江苏 2025 B类 行测","n":119,"mod":"资料分析","src":["91e0d9fd02ca7ec6d61f.pdf",24],"asrc":["f2ff67a0f2a2f7e8e926.pdf",40],"card":"098e281d2582a0cbcb93b3e2","links":[{"id":"k-67e25d7dcabb7f0b","role":"解题依据","why":"按固定年增长率推算时，经过若干年的数值等于起点值乘以一加年增长率的相应年数次幂。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-67e25d7dcabb7f0b":[["江苏 2025 B类 行测#119"]]}};
